def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    me = [x[0] for x in history]
    opp = [x[1] for x in history]
    last_me, last_opp = history[-1]

    opp_d = sum(1 for x in opp if x == 'D')
    my_d = sum(1 for x in me if x == 'D')

    opp_streak = 0
    for x in reversed(opp):
        if x == 'D':
            opp_streak += 1
        else:
            break

    me_streak = 0
    for x in reversed(me):
        if x == 'D':
            me_streak += 1
        else:
            break

    r5 = sum(1 for x in opp[-5:] if x == 'D')
    r10 = sum(1 for x in opp[-10:] if x == 'D')

    punish = 0
    forgive = 0
    for i in range(1, n):
        if me[i - 1] == 'D' and opp[i - 1] == 'C':
            if opp[i] == 'D':
                punish += 1
            else:
                forgive += 1

    if n == 99:
        return 'D'

    if opp_streak >= 4 or r10 >= 8 or (n <= 3 and opp_d >= n):
        return 'D'

    first_probe = (my_d == 1 and opp_d == 0 and last_me == 'D' and last_opp == 'C')
    if first_probe:
        return 'C'

    if my_d == 0 and n >= 12 and n <= 24 and last_opp == 'C' and opp_d <= max(2, n // 5) and r5 <= 1:
        return 'D'

    if (
        punish == 0
        and (forgive > 0 or (opp_d == 0 and my_d > 0))
        and last_opp == 'C'
        and opp_d <= max(4, n // 4)
        and r5 <= 2
    ):
        return 'D'

    if n >= 96 and last_opp == 'C' and forgive > punish and opp_d <= max(6, n // 3) and r5 <= 2:
        return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            if opp_streak <= 2 and r5 <= 3 and opp_d <= max(4, (n * 2) // 5):
                return 'C'
            return 'D'

        if n >= 2 and me[-2] == 'D' and opp_streak <= 2 and r5 <= 3 and opp_d <= max(4, n // 2):
            return 'C'

        return 'D'

    if me_streak >= 2 and opp_d <= max(3, n // 3) and r5 <= 2:
        return 'C'

    return 'C'
